var t = 0.0;
var dt;
var r;
var n = 255;
var s = 1;              // scale: changed later based on window size
var px_size = 1;        // pixel size: changed later based on window size
var dimen = 1;					// canvas size: changed later based on window size

function setup() {
	createCanvas(windowWidth, windowHeight);
	colorMode(RGB, 255);
	dimen = max(windowWidth, windowHeight)
  px_size = int(dimen / 512);
  s = 2 * dimen / 9;
	dt = PI / 400;		// p5js's PI constant isn't defined outside 
	r = PI * 2 / 235;
}

function draw() {
  background(0);
  translate(windowWidth / 2, windowHeight / 2);
  let x = 0;
  let v = 0;
  let u = 0;
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      u = sin(i + v) + sin(r * i + x);
      v = cos(i + v) + cos(r * i + x);
      x = u + t;
      stroke(i, j, n - (i + j) / 2);
      rect(s * u, s * v, px_size, px_size);
    }
  }
  t = t + dt;
}
